solution.solution.cpp:
#include <cstdint>
#include <map>
#include <set>
#include <string>
#include <vector>

std::uint32_t tagValue(const std::string& shown)
{
    std::uint32_t v{ 0 };
    for (int i{ 0 }; i < 4; ++i)
    {
        const unsigned char c{ i < static_cast<int>(shown.size()) ? static_cast<unsigned char>(shown[static_cast<std::size_t>(i)]) : static_cast<unsigned char>(' ') };
        v |= static_cast<std::uint32_t>(c) << (8 * i);
    }
    return v;
}

std::string tagText(std::uint32_t tag)
{
    std::string s;
    for (int i{ 0 }; i < 4; ++i)
    {
        const char c{ static_cast<char>((tag >> (8 * i)) & 0xFF) };
        s += (c >= 32 && c < 127) ? c : '.';
    }
    return s;
}

class PoolTracker
{
public:
    int allocate(std::size_t bytes, std::uint32_t tag)
    {
        if (bytes == 0) return 0;
        const int h{ m_next++ };
        m_live[h] = { bytes, tag };
        return h;
    }

    std::string free(int handle, std::uint32_t tag)
    {
        auto it{ m_live.find(handle) };
        if (it == m_live.end()) return m_freed.count(handle) ? "double free" : "unknown";
        if (it->second.tag != tag) return "tag mismatch";
        m_live.erase(it);
        m_freed.insert(handle);
        return "ok";
    }

    std::size_t bytesInUse(std::uint32_t tag) const
    {
        std::size_t total{ 0 };
        for (const auto& [h, a] : m_live) if (a.tag == tag) total += a.bytes;
        return total;
    }

    std::vector<std::string> leaks() const
    {
        std::map<std::string, std::pair<int, std::size_t>> byTag;
        for (const auto& [h, a] : m_live) { auto& e{ byTag[tagText(a.tag)] }; ++e.first; e.second += a.bytes; }
        std::vector<std::string> out;
        for (const auto& [tag, e] : byTag)
            out.push_back(tag + ": " + std::to_string(e.first) + (e.first == 1 ? " allocation, " : " allocations, ") + std::to_string(e.second) + " bytes");
        return out;
    }

private:
    struct Allocation { std::size_t bytes; std::uint32_t tag; };
    std::map<int, Allocation> m_live;
    std::set<int> m_freed;
    int m_next{ 1 };
};

unitTests:
using Lines = std::vector<std::string>;
TEST("tags") {
    CHECK_EQ(tagValue("Cirn"), 0x6E726943u); CHECK_EQ(tagText(0x6E726943u), std::string("Cirn")); CHECK_EQ(tagText('nriC'), std::string("Cirn"));
    CHECK_EQ(tagText(tagValue("Ab")), std::string("Ab  ")); CHECK_EQ(tagText(tagValue("Toolong")), std::string("Tool")); CHECK_EQ(tagText(0x00410141u), std::string("A.A."));
}
TEST("allocations and frees") {
    PoolTracker p; const std::uint32_t cirn = tagValue("Cirn"), cirb = tagValue("CirB");
    const int a = p.allocate(64, cirn), b = p.allocate(32, cirn), c = p.allocate(4096, cirb);
    CHECK_EQ(a, 1); CHECK_EQ(c, 3); CHECK_EQ(p.allocate(0, cirn), 0); CHECK_EQ(p.bytesInUse(cirn), std::size_t{ 96 });
    CHECK_EQ(p.free(a, cirb), std::string("tag mismatch")); CHECK_EQ(p.bytesInUse(cirn), std::size_t{ 96 });
    CHECK_EQ(p.free(a, cirn), std::string("ok")); CHECK_EQ(p.free(a, cirn), std::string("double free")); CHECK_EQ(p.free(99, cirn), std::string("unknown"));
    CHECK_EQ(p.leaks(), (Lines{ "CirB: 1 allocation, 4096 bytes", "Cirn: 1 allocation, 32 bytes" }));
    p.free(b, cirn); p.free(c, cirb); CHECK(p.leaks().empty());
}

